messages.en.stormScopeBody = 'It intercepts both ir_storm and other/ir_storm. Returning None on every other route preserves ordinary remotes, TV Be Gone and IR Jammer. Remove the route check to intercept every Deadcow IR transmission.'
messages.en.stormModify = 'Change frequency or pattern, then let Deadcow continue sending.'
messages.en.stormHandle = 'The plugin sent the signal; skip the built-in transmitter and report success.'
