messages.ru.tocReflection = 'Java reflection'
messages.ru.reflectionTitle = 'Помощники Java reflection'
messages.ru.reflectionLead = 'Эти методы ищут классы приложения и DEX-модулей объявленных зависимостей. Они умеют описывать приватные члены, читать и менять поля, вызывать подходящий метод и создавать объект. Они не устанавливают method hook и не перехватывают будущие вызовы.'
messages.ru.reflectionFind = 'Возвращает Class или None через ClassLoader приложения и зависимостей.'
messages.ru.reflectionInspect = 'Возвращает className, унаследованные поля, методы, конструкторы, типы параметров и признаки static.'
messages.ru.reflectionGet = 'Читает публичное или приватное поле объекта. Для статического поля передайте Class.'
messages.ru.reflectionSet = 'Записывает публичное или приватное поле объекта. Для статического поля передайте Class.'
messages.ru.reflectionInvoke = 'Вызывает первую совместимую перегрузку по имени, числу аргументов и их runtime-типам. Для статического метода передайте Class.'
messages.ru.reflectionNew = 'Вызывает первый совместимый объявленный конструктор, включая приватный.'
messages.ru.reflectionLimitsTitle = 'Совместимость reflection'
messages.ru.reflectionLimitsBody = 'Приватные имена и сигнатуры могут меняться между сборками Deadcow. Обрабатывайте исключения, объявляйте зависимость от библиотеки, самостоятельно проверяйте версию приложения и предпочитайте стабильные хуки экранов, поверхностей, действий и сервисов. Выбор перегрузки не выполняет произвольное преобразование типов.'
messages.ru.reflectionHelpers = 'Помощники reflection'
messages.ru.reflectionBridgeHelpers = 'Бридж reflection'
messages.ru.dexLimitsTitle = 'Ограничения и жизненный цикл'
messages.ru.dexLimitsBody = 'Размер .deadcowplugin может достигать 48 МиБ, а каждый декодированный DEX/JAR/APK — 32 МиБ. При отключении, удалении или обновлении библиотеки Deadcow сначала автоматически отключает активные зависимые плагины; включите потребителей снова после готовности библиотеки. Android не умеет выгружать Class после использования кода. Deadcow удаляет ссылки на загрузчики и экспорты при остановке владельца, но полностью гарантированная выгрузка после обновления возможна только перезапуском процесса. Делайте имена экспортов глобально уникальными и закрывайте потоки, receiver, сокеты и оборудование в on_plugin_unload.'

messages.fr = {"skip": "Passer au contenu", "navHome": "Accueil", "navDocs": "Documentation Plugins", "heroEyebrow": "Arsenal sans-fil Android open source", "heroTitleA": "Hack the", "heroTitleB": "World.", "heroLead": "Deadcow rassemble les technologies Bluetooth, infrarouge, NFC, HID et réseau dans une interface Material 3 Expressive pour la communauté CDC et le collectif Deadcow.", "download": "Télécharger APK", "androidApp": "Application Android native", "badgeText": "Laboratoire sans-fil de poche", "plugins": "Plugins", "featureEyebrow": "Une application. Des possibilités infinies.", "featureTitle": "Un arsenal conçu pour l'exploration et le pentest.", "featureLead": "Scannez, analysez, contrôlez et expérimentez les protocoles sans-fil depuis votre smartphone Android.", "featureWirelessTitle": "Bluetooth & Sans-fil", "featureWirelessBody": "Découvrez les périphériques BLE, testez l'audio Bluetooth, travaillez avec l'émulation HID et analysez les signaux environnants.", "featureIrTitle": "Outils Infrarouge", "featureIrBody": "Télécommandes universelles, TV-B-Gone, base de données IR complète avec matériel intégré ou émetteur externe.", "featureNfcTitle": "NFC & Réseaux", "featureNfcBody": "Lisez les badges NFC, inspectez les réseaux locaux et gardez vos outils de diagnostic à portée de main.", "featurePluginsTitle": "Plugins Python Puissants", "featurePluginsBody": "Créez des écrans complets, greffez des actions et ajoutez des intégrations matérielles via un simple fichier script Python.", "pluginEyebrow": "Conçu pour être étendu", "pluginTitle": "Transformez une idée en outil Deadcow.", "pluginLead": "Le moteur de plugins expose une interface expressive, des hooks d'application et des capacités Android via une API Python claire.", "pluginPointOne": "Construisez des écrans Material 3 complets", "pluginPointTwo": "Étendez les fonctionnalités et actions existantes", "pluginPointThree": "Intégrez le Bluetooth, Wi-Fi, USB, IR et plus", "readDocs": "Lire la documentation", "downloadEyebrow": "Prêt à explorer ?", "downloadTitle": "Obtenez la dernière version de Deadcow.", "downloadLead": "Téléchargez l'APK depuis GitHub Releases et transformez votre smartphone en laboratoire d'audit sans-fil.", "openReleases": "Voir les Releases", "footerTagline": "Hack the World. Dédié à la CDC et aux pirates Deadcow.", "copy": "Copier", "integrationTruthTitle": "Points d'intégration, pas de correctifs arbitraires", "integrationTruthBody": "Les crochets d'écran fonctionnent pour chaque itinéraire hébergé par Deadcow. Les hooks d’action et de service fonctionnent uniquement lorsque l’application distribue explicitement un point d’intégration nommé. Un plugin n'intercepte pas automatiquement toutes les fonctions Kotlin.", "screenHookTitle": "Crochets d'écran en détail", "screenHookLead": "Les routes et les modèles ne sont pas sensibles à la casse. L'astérisque correspond à n'importe quel nombre de caractères. Si plusieurs plugins correspondent, une priorité plus élevée l'emporte lorsqu'une seule contribution peut être utilisée.", "modeOverlay": "Rend un calque transparent en taille réelle sur l'écran existant.", "modeTop": "Place l'interface utilisateur du plugin dans une surface Material en haut de l'écran.", "modeBottom": "Place l’interface utilisateur du plugin au-dessus de la zone de navigation inférieure.", "modeFab": "Place l’interface utilisateur compacte du plugin à l’extrémité inférieure avec un remplissage sécurisé pour la navigation.", "modeReplace": "Le remplacement prioritaire recouvre visuellement l’écran intégré. Son écran Compose sous-jacent existe toujours, il s’agit donc d’un remplacement de l’interface utilisateur plutôt que d’un correctif de bytecode.", "routePatternsTitle": "Modèles d'itinéraire utiles", "routePatternsBody": "Utilisez l'événement de navigation lors du développement pour inspecter l'itinéraire actuel. Les routes avec des arguments sont signalées comme modèle de navigation, par exemple nfc_result/{id}.", "logicHooksTitle": "Crochets d'action et services", "logicHooksLead": "Les crochets d’action forment un pipeline classé par priorité. Les services forment une liste de fournisseurs classés par priorité. Les deux utilisent des charges utiles compatibles JSON.", "returnNone": "Continuez sans modifier l'action.", "returnPayload": "Remplacez la charge utile transmise aux hooks de priorité inférieure et à l’implémentation intégrée.", "returnHandled": "Marquez l'action gérée par le plugin. Utilisez le résultat pour renvoyer une valeur.", "returnCancel": "Arrêtez la chaîne à crochet et annulez l'opération intégrée.", "returnFalse": "Annulez immédiatement. True marque l'action traitée.", "currentPointsTitle": "Points d'intégration disponibles dès maintenant", "currentPointsBody": "Deadcow expose la transmission infrarouge partagée ainsi que la sélection de section Bluetooth, toutes les actions, les modes BLE, les préréglages publicitaires et chaque paquet publicitaire BLE sortant. La liste exacte complète se trouve dans le catalogue des crochets.", "fullApiTitle": "Carte d'exécution complète", "fullApiLead": "Ces groupes reflètent la surface appelable actuellement livrée avec Deadcow. Ouvrez un groupe pour voir le nom de chaque assistant public.", "baseHelpers": "Assistants de plugins", "uiHelpers": "Générateurs d'interface utilisateur Compose natifs", "bridgeHelpers": "Pont d'exécution", "androidHelpers": "Android, fichiers et Bluetooth avancé", "deviceHelpers": "Outils pour appareils sans fil, réseau et surélevés", "docsEyebrow": "Documentation du développeur", "docsTitle": "Construisez quelque chose de puissant pour Deadcow.", "docsLead": "Un plugin est un fichier Python lisible avec l'extension .deadcowplugin. Il peut créer des écrans, intégrer du matériel et étendre les fonctionnalités Deadcow existantes.", "quickStart": "Démarrage rapide", "examples": "Exemples", "onThisPage": "Sur cette page", "tocOverview": "Aperçu", "tocMetadata": "Métadonnées", "tocQuick": "Démarrage rapide", "tocUi": "Interface utilisateur expressive", "tocIntegration": "Intégration d'applications", "tocApis": "API Android et appareils", "tocLifecycle": "Cycle de vie", "tocInstall": "Installation et sécurité", "overviewTitle": "Ce qu'un plugin peut faire", "overviewLead": "Les plugins s'exécutent dans Deadcow et utilisent le même système de conception et la même couche d'accès matériel que l'application.", "capScreens": "Créer des écrans complets", "capScreensBody": "Composez des outils expressifs Material 3 multi-écrans avec état et rappels.", "capHooks": "Étendre Deadcow", "capHooksBody": "Ajoutez des superpositions, des FAB, remplacez des écrans et accrochez des actions nommées.", "capHardware": "Intégrer le matériel", "capHardwareBody": "Travaillez avec BLE, Bluetooth classique, Wi-Fi, USB, NFC et infrarouge.", "capSystem": "Utiliser les fonctionnalités d'Android", "capSystemBody": "Accédez aux activités, aux intentions, au stockage, au shell, à Root et Shizuku lorsqu'ils sont disponibles.", "trustedTitle": "Le pouvoir vient avec la responsabilité", "trustedBody": "Les plugins sont du code Python exécutable. Installez uniquement les fichiers auxquels vous faites confiance et examinez la source avant d'accorder un accès élevé.", "metadataTitle": "Métadonnées du fichier", "metadataLead": "Déclarez l'identité du plugin au début du fichier. Deadcow l'utilise pour la bibliothèque d'aperçus et de plugins.", "metaId": "Identifiant unique stable", "metaName": "Nom d'affichage", "metaVersion": "Version de sortie", "metaAuthor": "Auteur ou équipe", "metaDescription": "Bref résumé", "metaIcon": "Nom de l'icône des symboles matériels", "quickTitle": "Votre premier plugin", "quickLead": "Sous-classe BasePlugin, décrivez un écran et laissez Deadcow le restituer avec le jeu de couleurs de l'application active.", "uiTitle": "Interface utilisateur expressive de Python", "uiLead": "Les créateurs d’interface utilisateur créent des composants Compose natifs. Les mises à jour d'état et les rappels restent dans votre fichier de plugin.", "integrationTitle": "Étendre les fonctionnalités Deadcow existantes", "integrationLead": "Les hooks permettent à un plugin de participer aux écrans et à la logique actuels sans copier l'implémentation de l'application.", "hookScreenBody": "Ajoutez une superposition ou un FAB à un itinéraire, ou remplacez un écran par votre propre écran de plugin.", "hookActionBody": "Observez, transformez, gérez ou annulez une action nommée avant l'exécution de l'implémentation par défaut.", "serviceBody": "Fournir une nouvelle implémentation pour une fonctionnalité telle qu'un émetteur infrarouge externe.", "apisTitle": "API Android et appareils", "apisLead": "Le pont donne aux plugins un accès contrôlé à la plate-forme et au matériel sans fil disponible sur l'appareil.", "apiContext": "Contexte de l'application", "apiActivity": "Activité actuelle", "apiAndroid": "Intentions et stockage", "apiDevice": "Bluetooth, Wi-Fi, NFC, IR et USB", "apiShell": "Commandes shell", "apiRoot": "Accès racine", "apiShizuku": "Accès Shizuku", "lifecycleTitle": "Cycle de vie du plugin", "lifecycleLead": "Gardez la configuration, l'interface utilisateur et le nettoyage prévisibles en utilisant les méthodes de cycle de vie d'exécution.", "lifeLoad": "Plugin chargé", "lifeScreen": "Écran créé", "lifeEvent": "Événements et actions", "lifeUnload": "Plugin déchargé", "installTitle": "Installer, mettre à jour et récupérer", "installLead": "Deadcow gère les fichiers .deadcowplugin et affiche une feuille de matériau compacte et partiellement développée avant l'exécution de tout code. L'installation ferme la feuille et confirme le succès avec un toast Deadcow.", "stepOpen": "Ouvrir le fichier", "stepOpenBody": "Appuyez sur un fichier .deadcowplugin dans votre gestionnaire de fichiers et choisissez Deadcow.", "stepReview": "Examiner les métadonnées", "stepReviewBody": "Passez en revue l'icône, l'auteur, la version, la description et les fonctionnalités détectées ou déclarées telles que le chargement DEX, les téléchargements, les fichiers, les hooks, Bluetooth, Wi-Fi, USB, IR, Root, Shizuku et Shell.", "stepInstall": "Installer", "stepInstallBody": "Le code ne démarre qu'après avoir appuyé sur Installer. La réouverture du fichier le met à jour.", "safeTitle": "Mode sans échec automatique", "safeBody": "Si l'application se ferme pendant l'exécution du code du plugin, le prochain lancement désactive chaque plugin et propose un journal des plantages. Vous pouvez ensuite activer les plugins un par un.", "docsCtaTitle": "Prêt à construire ?", "docsCtaBody": "Commencez par les exemples du référentiel Deadcow.", "viewExamples": "Voir des exemples", "metaLibrary": "Charger avant les plugins ordinaires et marquer le fichier comme bibliothèque", "metaDesignLibrary": "Charger tôt et marquer le fichier comme bibliothèque de conception", "settingsContribTitle": "Paramètres du plugin natif", "settingsContribBody": "api.registerSettings ajoute les sections Material 3 Expressive directement aux paramètres Deadcow. Les commutateurs et les curseurs persistent dans le magasin de plugins et émettent settings_changed ; les éléments de navigation et de carte ouvrent les écrans du plugin.", "lifecycleAliasesTitle": "Noms de cycle de vie acceptés", "lifecycleAliasesBody": "Chargez et activez les rappels exécutés au démarrage de la session. Désactivez et déchargez les rappels exécutés lorsqu'il s'arrête. Les gestionnaires on_<event> spécifiques ont priorité sur on_event.", "stormHookTitle": "Exemple : intercepter chaque transmission IR Storm", "stormHookLead": "IR Storm appelle l'action de transmission infrarouge partagée une fois pour chaque signal. La charge utile de l'action ne contient pas l'écran source, donc un plugin qui cible uniquement IR Storm doit mémoriser le dernier événement de navigation.", "stormPayloadName": "Nom du signal ou du bouton si disponible", "stormPayloadFrequency": "Fréquence porteuse en hertz", "stormPayloadPattern": "Durées alternées des marques et des espaces en microsecondes", "stormPayloadProtocol": "Etiquette du protocole lorsqu'elle est connue", "stormPayloadCode": "Valeur codée d'origine lorsqu'elle est disponible", "stormPayloadTimings": "Représentation temporelle originale lorsqu'elle est disponible", "stormScopeTitle": "Ce que cet exemple affecte", "stormScopeBody": "Il intercepte à la fois ir_storm et other/ir_storm. Le retour de None sur tous les autres itinéraires préserve les télécommandes ordinaires, TV Be Gone et IR Jammer. Supprimez la vérification d'itinéraire pour intercepter chaque transmission Deadcow IR.", "stormModify": "Changez la fréquence ou le modèle, puis laissez Deadcow continuer l'envoi.", "stormHandle": "Le plugin a envoyé le signal ; ignorez l'émetteur intégré et signalez le succès.", "stormCancel": "Bloquez le signal sans l'envoyer.", "stormAdapterTitle": "Émetteurs intégrés et externes", "stormAdapterBody": "L'exemple est envoyé via ConsumerIrManager intégré à Android sans ré-entrer dans le hook. Pour un émetteur USB, remplacez uniquement send_to_external_ir par le protocole de périphérique implémenté via api.getAndroid(), les classes USB Android ou un fournisseur de services.", "tocHookCatalog": "Catalogue de crochets", "hookCatalogTitle": "Catalogue complet de crochets", "hookCatalogLead": "Chaque itinéraire d'écran, action nommée, opération de service et événement actuellement émis par Deadcow.", "hookCatalogRuleTitle": "L'appel et l'interception sont différents", "hookCatalogRuleBody": "Les listes d'API Android et Device contiennent des fonctions qu'un plugin peut appeler. Seules les entrées ci-dessous peuvent être interceptées. L'enregistrement de hook_action(\"*\") n'expose pas les fonctions que Deadcow ne distribue jamais.", "actionCatalogTitle": "Crochets d'action nommés", "catalogName": "Nom", "catalogHandler": "Gestionnaire Python", "catalogWhere": "Déclenché par", "infraredActionWhere": "Chaque envoi via le backend IR partagé : IR Storm, IR Jammer, TV Be Gone, télécommandes universelles et base de données.", "actionCatalogNote": "L'inscription utilise hook_action (nom, priorité). Les caractères génériques sont pris en charge : bluetooth.*, bluetooth.ble.* et bluetooth.advert.preset.* peuvent intercepter des familles entières.", "serviceCatalogTitle": "Prestataires de services et opérations", "infraredAvailableWhere": "Lorsque Deadcow vérifie si un émetteur IR est disponible.", "infraredTransmitWhere": "Après les hooks d’action, avant le repli intégré de ConsumerIrManager.", "serviceCatalogNote": "Inscription : provide_service(\"infrared.transmitter\", priorité). Les identifiants de service sont exacts et n'utilisent pas de correspondance par caractères génériques.", "eventCatalogTitle": "Événements", "genericEventPayload": "Repli pour les événements sans méthode on_<event> spécifique", "routeCatalogTitle": "Tous les itinéraires d'écran disponibles pour hook_screen", "routeCatalogLead": "Il existe 108 itinéraires dans les hôtes de navigation actuels. Les itinéraires paramétrés correspondent à leur modèle présenté ci-dessous, y compris les accolades.", "allRoutesTitle": "108 noms d'itinéraires exacts", "allRoutesHint": "Utilisez un nom exact ou un motif astérisque", "newHookTitle": "Lorsqu'une fonction est absente de ce catalogue", "newHookBody": "Il ne peut actuellement pas être intercepté via l’API publique du plugin hook. Deadcow doit ajouter EnsureActionHooks(name, payload) ou EnsureServices(service, operation, payload) sur ce site d'appel Kotlin avant que les auteurs du plugin puissent l'accrocher.", "manifestRulesTitle": "Règles d'analyse du manifeste", "manifestRulesBody": "Le fichier est du texte UTF-8 et peut faire au maximum 48 Mio. Les champs de chaîne doivent être des affectations de niveau supérieur entre guillemets simples ou doubles. id est en minuscules, les caractères invalides deviennent des traits de soulignement et le résultat est limité à 64 caractères. Les champs manquants renvoient au nom de fichier, à la version 1.0 et à l'extension de l'icône.", "libraryTruthTitle": "Plugins et dépendances de bibliothèque", "libraryTruthBody": "Les plugins de bibliothèque démarrent avant les consommateurs. __dependencies__ déclare les identifiants de plugin requis, détermine l'ordre de démarrage et empêche un consommateur de démarrer lorsqu'une dépendance est manquante ou désactivée. Les classes et objets Java peuvent être exportés par nom et importés par des plugins dépendants.", "runtimeTruthTitle": "Format public et exécution", "runtimeTruthBody": "Un fichier ouvert ou partagé en tant que .deadcowplugin est toujours exécuté par le runtime Python intégré. Le référentiel contient toujours un runtime de compatibilité JavaScript interne pour les plugins .js précédemment stockés, mais il ne s'agit pas du format de création public .deadcowplugin documenté.", "baseSignatureTitle": "API BasePlugin complète", "baseSignatureBody": "Ces aides délèguent au pont natif. api et ui sont également disponibles directement sur soi.", "moduleSectionsTitle": "Où add_module peut placer une carte", "moduleSectionsBody": "Les sections intégrées sont INFRAROUGE, BLUETOOTH, AUTRES et PLUGINS. Les alias tels que ir, bt, ble, misc et les noms localisés sont normalisés ; tout autre texte crée une section personnalisée. l'ordre trie les cartes, l'écran choisit l'écran du plugin et l'icône accepte la syntaxe de l'icône matérielle.", "uiTextStyles": "titreLarge/Medium/Small, titreLarge/Medium/Small, bodyLarge/Medium/Small et étiquetteLarge/Medium/Small ; camelCase et Snake_case sont acceptés.", "uiColorValues": "primaire/accent, sourdine/secondaire, erreur/rouge, succès/vert, avertissement/orange ou #RGB/#ARGB/#RRGGBB/#AARRGGBB.", "uiIconValues": "Un alias intégré ou toute icône de matériau groupée comme style: nom : rempli, décrit, arrondi, net, bicolore ou miroir automatique.", "uiImageValues": "chemin de l'actif, URL de l'actif://, data:image/...;URI base64 ou Base64 brut. Échelle : ajustement, recadrage, remplissage, remplissageLargeur, remplissageHauteur, intérieur ou aucun.", "uiCallbackValues": "Le clic ne reçoit aucune valeur ; les champs de texte reçoivent str, les commutateurs et les cases à cocher bool, les curseurs float, les tabulations int et les options contrôlent la valeur sélectionnée.", "uiWebViewValues": "Charge soit l'URL, soit le HTML, avec le stockage JavaScript et DOM activé. Traitez le contenu distant et intégré comme une interface utilisateur exécutable fiable.", "uiSignatureTitle": "Signatures UiFactory complètes", "uiSignatureBody": "Chaque argument ci-dessous est pris en charge par le runtime Python. Les dimensions et l'espacement utilisent dp.", "settingsHeaderSchema": "titre", "settingsSwitchSchema": "clé, titre, sous-titre, valeur par défaut : bool", "settingsSliderSchema": "clé, titre, sous-titre, min, max, par défaut, étapes", "settingsNavSchema": "titre, sous-titre, icône, écran ; ouvre toujours le plugin/{pluginId}/{screen}", "settingsCardSchema": "titre, sous-titre, icône et écran optionnel", "settingsStorageTitle": "Stockage et mises à jour", "settingsStorageBody": "Les valeurs des commutateurs et des curseurs utilisent le même magasin JSON par plugin que get_setting/set_setting. L'hôte conserve une valeur avant d'appeler on_setting_changed({key, value}); les curseurs émettent l’événement lorsque l’interaction se termine.", "settingKeysTitle": "D'où viennent les clés de réglage", "settingKeysBody": "Il n’existe pas de catalogue de clés prédéfini. L'auteur du plugin crée n'importe quelle clé de chaîne et utilise la même orthographe lors de la lecture, de l'écriture ou de la déclaration d'un élément de paramètres. Les clés n'entrent en collision qu'à l'intérieur du même plugin car chaque pluginId a un magasin séparé. Préférez les noms stables tels que capture_enabled ou radio.power ; changer une clé crée un nouveau paramètre.", "settingKeyContract": "Toute chaîne non vide choisie par le plugin. Il n'y a actuellement aucune clé d'hôte réservée.", "settingValueContract": "Toute valeur compatible avec json.dumps : None, bool, number, str, list ou dict.", "settingDefaultContract": "get_setting renvoie la valeur par défaut fournie lorsque la clé n'a jamais été enregistrée.", "settingLifetimeContract": "Les valeurs survivent aux redémarrages et sont activées/désactivées. La suppression du plugin supprime l’intégralité de son magasin de paramètres.", "layerBase": "Aides pratiques pour les modules, la navigation, l'état, les hooks d'écran/action/service et l'accès au shell.", "layerUi": "Construit une arborescence d'interface utilisateur compatible JSON rendue en tant que composants natifs de Compose Material 3.", "layerBridge": "Enregistrement, accès au contexte/activité, paramètres JSON persistants, exécution et analyse BLE par lots.", "layerAndroid": "Intégration directe Android : stockage, actifs, médias, crypto, IR, Bluetooth classique, RFCOMM, GATT, serveur/annonceur BLE, Wi-Fi et NSD.", "layerDevice": "Opérations sans fil, NFC, réseau, Root et Shizuku de niveau supérieur avec des résultats orientés JSON.", "layerJava": "Chaquopy peut importer directement des classes Android et Java lorsqu'un assistant de pont ne suffit pas.", "apiContractsTitle": "Contrats de données et d’exécution", "apiContractsBody": "La plupart des assistants matériels n'ouvrent pas les invites d'autorisation. Vérifiez les méthodes hasPermission/capability et demandez des autorisations Android via les API d'activité si nécessaire. Les analyses de longue durée, GATT, RFCOMM, capteurs, audio, publicité, serveurs BLE, NSD et Wi-Fi P2P doivent être arrêtés pendant on_plugin_disable/on_plugin_unload.", "bridgeSignatureTitle": "Signatures de pont directes", "bridgeSignatureBody": "Utilisez les wrappers BasePlugin là où ils existent. Les méthodes de pont direct préservent les types de retour Java ; les paramètres et les méthodes de commande échangent du texte JSON.", "deviceCompleteTitle": "Contrôle des appareils et outils système", "deviceCompleteBody": "État de l'appareil, commandes radio et opérations Root avancées", "genericActionBody": "Remplacement générique pour chaque action enregistrée sans méthode hook_<normalized_action> correspondante. Les points et autres caractères non alphanumériques sont normalisés en traits de soulignement.", "serviceAvailableContract": "Rend un émetteur externe considéré comme disponible ; {\"ok\": true} ou raw True sont également acceptés.", "serviceTransmitContract": "Arrête le repli du fournisseur et signale le succès. handled false permet au prochain fournisseur ou au ConsumerIrManager intégré de s'exécuter.", "serviceGenericContract": "Solution de secours générique lorsque service_<service>_<opération> n'est pas défini.", "screenResolverContract": "Moteur de rendu principal. main accepte également create_screen ou screen_main. Les écrans manquants affichent un espace réservé d’erreur natif.", "callbackContract": "Les callables Python transmis aux générateurs d'interface utilisateur reçoivent uniquement le type de valeur produit par ce composant. La déclaration de moins d'arguments de position est prise en charge.", "eventResolverContract": "Un gestionnaire d'événements spécifique gagne ; sinon, on_event(name, payload) est appelé.", "actionResolverContract": "Le gestionnaire d’actions normalisé spécifique gagne ; sinon on_action(action, payload) est appelé.", "serviceResolverContract": "Un gestionnaire de service normalisé spécifique gagne ; sinon, on_service(id, operation, payload) est appelé.", "refreshContract": "Invalide l'interface utilisateur du plugin enregistré afin que les fonctions d'écran s'exécutent à nouveau avec le dernier état du plugin.", "installPreviewContract": "Lit les métadonnées et la taille sans exécuter Python ; indique si le même identifiant est déjà installé.", "installUpdateContract": "Enregistre la source en privé et la démarre immédiatement, sauf si le mode sans échec est actif. L'installation du même identifiant remplace la session précédente et conserve son état épinglé.", "installToggleContract": "Démarre ou arrête le runtime et supprime tous les modules, paramètres, écrans, services et actions enregistrés lorsqu'ils sont désactivés.", "installShareContract": "Les épingles changent l’ordre. Share exporte la source originale sous le nom application/x-deadcow-plugin avec l'extension .deadcowplugin.", "installDeleteContract": "Arrête le runtime et supprime définitivement la source, les métadonnées, les enregistrements et le magasin de paramètres privés du plugin.", "installFailureContract": "Un plugin qui ne peut pas démarrer est enregistré désactivé lors de l'installation ; une source stockée corrompue peut être mise en quarantaine comme .broken lors de la restauration.", "safeDetailsTitle": "Comportement du mode sans échec", "safeDetailsBody": "La feuille de récupération explique qu'une erreur de plug-in a fermé l'application et propose de copier le journal ou de désactiver le mode sans échec. Le rejeter laisse le mode sans échec activé et un élément persistant reste sur l’écran Plugins. Lorsqu'il est actif, chaque plugin est désactivé et ne peut pas être activé tant que le mode sans échec n'est pas désactivé.", "coreReplaceTitle": "Remplacer les écrans centraux complets", "coreReplaceBody": "Utilisez remplacer par d'autres, Bluetooth ou paramètres pour couvrir l'intégralité de l'écran principal. Bluetooth expose également trois cibles de sous-écran en direct, de sorte qu'un plugin peut remplacer All, BLE ou Advert indépendamment.", "bleHookTitle": "Exemple : remplacer la logique publicitaire BLE", "bleHookLead": "bluetooth.advertising.transmit s'exécute pour les préréglages d'annonces personnalisés et les paquets générés par chaque mode spam BLE intégré. Modifiez les données pour réécrire le paquet, renvoyez l'annulation pour le bloquer ou traitez-les après la transmission avec votre propre backend.", "bleModeApiTitle": "Ajoutez un mode BLE Spam de première classe", "bleModeApiLead": "register_ble_mode ajoute le plugin à côté des modes BLE intégrés en utilisant la même carte, le même état actif, le même délai partagé et le même comportement Stop All. Deadcow envoie ble_mode_start, ble_mode_stop et ble_mode_delay_changed uniquement au plugin propriétaire. Le plugin est propriétaire de sa boucle publicitaire et doit l'arrêter à la fois à l'arrêt et au déchargement.", "assetApiTitle": "Téléchargez et appliquez les ressources du plugin", "assetApiLead": "download_assets demande tous les fichiers en un seul lot. Chaque destination est confinée au répertoire privé de ce plugin ; maxBytes limite chaque réponse et sha256 peut la vérifier. Sauf si l'utilisateur a désactivé la confirmation dans Paramètres du plugin → Sécurité, Deadcow affiche le nom du plugin, le nombre de fichiers et la taille totale déclarée avant le transfert réseau. apply_asset importe un fichier enregistré dans un éditeur Bad USB d'origine, des télécommandes IR utilisateur ou un code HTML personnalisé QR Audio Spoofer.", "assetPathContract": "Renvoie le chemin absolu d'un emplacement dans le dossier privé du plugin pour les API Java et DEX.", "assetDownloadContract": "Les éléments acceptent l'URL, le chemin, sizeBytes, maxBytes, sha256 et les en-têtes. Le rappel reçoit {ok, files} sous forme de texte JSON.", "assetApplyContract": "Types pris en charge : bad_hid, ir_remote et qr_audio_html. Renvoie un dictionnaire de résultats analysé.", "bleAssetHelpers": "Modes BLE et ressources du plugin", "bleAssetBridgeHelpers": "BLE et pont d'actifs", "metaPermissions": "Capacités affichées avant l'installation ; Deadcow détecte également l'utilisation directe de l'API dans la source", "btSectionWhere": "Avant de basculer entre Tous, BLE et Annonce. la section ou l’index peut être modifié.", "btDeviceWhere": "Avant de sélectionner un appareil Bluetooth classique découvert.", "btIntervalWhere": "Lorsque le curseur Tous les intervalles change. Les intervalles peuvent être modifiés.", "btScanWhere": "Avant que la découverte classique et BLE ne commence sur All.", "btAllStartWhere": "Before All démarre les demandes d’appairage classiques répétées.", "btAllStopWhere": "Avant que tout arrête son fonctionnement actif.", "bleDelayWhere": "Avant de modifier le délai du mode BLE. les délais peuvent être modifiés.", "bleModeWhere": "Avant de basculer sur un mode BLE individuel.", "bleKitchenWhere": "Avant de basculer l'évier de cuisine.", "bleStopWhere": "Avant d'arrêter tous les modes BLE.", "bleSectionToggleWhere": "Avant de basculer entre tous les modes d'un groupe iOS, Samsung, Android, Windows, Xiaomi ou Phantom.", "bleSectionOpenWhere": "Avant d'ouvrir un écran de groupe BLE. La section peut être redirigée.", "advertAddWhere": "Avant d'enregistrer un nouveau préréglage d'annonce ; tous les champs peuvent être modifiés.", "advertUpdateWhere": "Avant de mettre à jour un préréglage d'annonce ; tous les champs peuvent être modifiés.", "advertDeleteWhere": "Avant de supprimer un préréglage d'annonce.", "advertStartWhere": "Avant de démarrer un préréglage ; les champs peuvent être modifiés ou le début peut être entièrement géré.", "advertStopWhere": "Avant d'arrêter un préréglage d'annonce.", "advertTransmitWhere": "Avant chaque paquet publicitaire sortant des modes Advert ou BLE intégré.", "advertisingStopWhere": "Avant l'arrêt d'un cycle de publicité ou d'un annonceur BLE intégré ; un backend externe peut arrêter sa propre transmission et gérer le retour.", "advertPayloadTitle": "charge utile bluetooth.advertising.transmit", "advertPayloadBody": "metadata.source est ble_spam ou advert ; L'annonce comprend également metadata.preset. data et scanResponse contiennent includeDeviceName, includeTxPowerLevel, manufactureData [{id,data}], serviceUuids et serviceData [{uuid,data}]. Les valeurs binaires sont en majuscules hexadécimales. Le renvoi d’une charge utile modifiée reconstruit les AdvertiseData natifs.", "virtualRoutesTitle": "Cibles du sous-écran Bluetooth", "virtualRoutesBody": "Il s’agit de cibles de crochet en direct à l’intérieur de l’itinéraire Bluetooth plutôt que de destinations de navigation. Ils prennent en charge tous les modes hook_screen.", "tocSdkReference": "Référence du SDK", "sdkReferenceTitle": "Référence du SDK appelable", "sdkReferenceLead": "Recherchez l'API publique complète. Chaque entrée comprend sa signature exacte, ses paramètres, son contrat de retour, ses exigences et un exemple d'appel Python.", "sdkReadingTitle": "Comment lire les contrats", "sdkReadingBody": "Un type nullable peut devenir None. Les actions booléennes indiquent si Android a accepté la demande, et non si un appareil distant l'a complétée. Les méthodes avec rappels se terminent de manière asynchrone. Les résultats JSON restent des chaînes jusqu'à ce que json.loads soit appelé.", "tocDexLibraries": "DEX et bibliothèques", "metaDependencies": "Identifiants de plugin requis chargés avant ce plugin", "surfaceHooksTitle": "Surfaces chromées de l'application", "surfaceHooksBody": "hook_surface cible l'interface utilisateur en dehors d'un itinéraire d'écran ordinaire. bottom_bar peut être superposé ou entièrement remplacé. Le remplacement suit la priorité du plugin et disparaît automatiquement lorsque le plugin est désactivé.", "surfaceCatalogTitle": "Surfaces hôtes accrochables", "surfaceCatalogBody": "Utilisez hook_surface plutôt que hook_screen pour l'interface utilisateur appartenant au shell de l'application.", "dexLibrariesTitle": "Chargement DEX et plugins de bibliothèque", "dexLibrariesLead": "Conservez un plugin sous la forme d'un fichier Python lisible tout en intégrant du code Java ou Kotlin compilé et en partageant des fonctionnalités natives avec d'autres plugins.", "dexTrustTitle": "DEX est un code natif de confiance", "dexTrustBody": "Un DEX chargé s'exécute dans le processus Deadcow avec les autorisations de l'application. Publiez toujours le SHA-256, vérifiez-le avant de le charger et n'exécutez jamais une charge utile téléchargée non fiable.", "dexEmbeddedTitle": "Intégrer et charger un DEX brut", "dexEmbeddedLead": "Stockez le DEX brut en Base64 dans le fichier .deadcowplugin. Deadcow supprime les espaces, les décode, vérifie SHA-256 et crée le chargeur de classe. Raw DEX utilise InMemoryDexClassLoader sur Android 8+ ; Les anciennes charges utiles JAR/APK Android et ZIP utilisent un fichier de cache de code privé en lecture seule et DexClassLoader.", "dexLoadBase64Contract": "Charge les octets bruts DEX, JAR ou APK stockés en Base64 et renvoie le module ClassLoader.", "dexLoadFileContract": "Copie et charge un fichier DEX/JAR/APK. Utilisez le stockage privé du plugin et vérifiez son résumé.", "dexClassContract": "Charge une classe à partir d'un module appartenant au plugin actuel.", "dexInstanceContract": "Appelle un constructeur accessible sans argument et renvoie l'objet Java.", "dexLoaderContract": "Renvoie un module ClassLoader ou None déjà chargé.", "dexDependencyLoaderContract": "Renvoie un chargeur parent d'application qui peut également résoudre les modules exportés par les dépendances déclarées.", "libraryExportsTitle": "Exporter des classes et des objets vivants", "libraryExportsLead": "Les exportations sont des références nommées locales au processus. Une bibliothèque est propriétaire de chaque classe et objet qu'elle exporte ; la désactivation, la mise à jour ou la suppression de cette bibliothèque supprime ses modules et ses exportations du registre.", "exportDexClassBody": "Résolvez et publiez une classe à partir du module DEX actuel.", "exportAppClassBody": "Publiez une classe Deadcow ou une classe de dépendance par son nom complet.", "exportJavaClassBody": "Publiez un objet Class déjà obtenu via la réflexion Java.", "exportJavaObjectBody": "Publiez un objet, un adaptateur, un contrôleur ou une façade Java en direct.", "importJavaClassBody": "Obtenez une exportation de classe nommée à partir de n’importe quelle dépendance activée.", "importJavaObjectBody": "Obtenez une exportation d’objet dynamique nommé à partir de n’importe quelle dépendance activée.", "javaExportsBody": "Inspectez tous les modules chargés et les noms de classe/objet exportés à des fins de diagnostic.", "sourceBridgeTitle": "Exposer les composants internes de Deadcow à partir de l'open source", "sourceBridgeLead": "Utilisez le référentiel pour rechercher un nom de classe JVM complet, puis exportez cette classe ou enveloppez-la dans une façade DEX stable. Les consommateurs devraient s'appuyer sur la façade de la bibliothèque au lieu de dupliquer un code de réflexion fragile.", "sourceBridgeBoundaryTitle": "Accès aux classes par rapport aux hooks hôtes", "sourceBridgeBoundaryBody": "L'exportation de classe permet la réflexion, la construction et les appels de méthodes ; il ne réécrit pas une fonction Compose déjà compilée. Utilisez hook_screen pour les écrans, hook_surface(\"bottom_bar\") pour le panneau de navigation, des crochets d'action pour la logique et des fournisseurs de services pour les backends matériels remplaçables. Une bibliothèque DEX peut cacher la réflexion derrière une façade stable partagée par d'autres plugins.", "dexLimitsTitle": "Limites et cycle de vie", "dexLimitsBody": "Un .deadcowplugin peut faire 48 Mio ; chaque charge utile DEX/JAR/APK décodée peut être de 32 Mio. La désactivation, la suppression ou la mise à jour d'une bibliothèque désactive automatiquement en premier les plugins dépendants activés ; réactivez les consommateurs lorsque la bibliothèque est prête. Android ne peut pas décharger une classe une fois que le code l'a référencée. Deadcow abandonne les chargeurs et exporte lorsque le propriétaire s'arrête, mais un redémarrage du processus est le seul déchargement complet garanti après une mise à jour. Conservez les noms d'exportation uniques au monde et fermez les threads, les récepteurs, les sockets et les descripteurs matériels dans on_plugin_unload.", "docsSearch": "Rechercher de la documentation", "tocStartGroup": "Commencer", "tocUiGroup": "Interface", "tocIntegrationGroup": "Intégration", "tocNativeGroup": "Code natif", "tocReferenceGroup": "Référence", "tocPluginSettings": "Paramètres du plugin", "tocScreenHooks": "Crochets pour écran", "tocSurfaceHooks": "Surfaces d'application", "tocLogicHooks": "Actions & prestations", "tocLibraryExports": "Exportations de bibliothèque", "tocReflection": "Réflexion Java", "reflectionTitle": "Aides à la réflexion Java", "reflectionLead": "Ces assistants recherchent l'application ainsi que les modules DEX des dépendances déclarées. Ils peuvent inspecter les membres privés, lire ou écrire des champs, appeler une méthode de correspondance et construire un objet. Ils n’installent pas de hook de méthode et n’interceptent pas les futurs appels.", "reflectionFind": "Renvoie une classe ou None à l’aide de l’application et des ClassLoaders de dépendances.", "reflectionInspect": "Renvoie className ainsi que les champs, méthodes, constructeurs, types de paramètres et indicateurs statiques hérités.", "reflectionGet": "Lit un champ d'instance public ou privé. Passez une classe pour un champ statique.", "reflectionSet": "Écrit un champ d'instance public ou privé. Passez une classe pour un champ statique.", "reflectionInvoke": "Appelle la première surcharge compatible par nom, nombre d'arguments et types d'exécution. Passez une classe pour une méthode statique.", "reflectionNew": "Appelle le premier constructeur déclaré compatible, y compris un constructeur privé.", "reflectionLimitsTitle": "Compatibilité de réflexion", "reflectionLimitsBody": "Les noms et signatures privés peuvent changer entre les versions de Deadcow. Détectez les exceptions, déclarez la dépendance de la bibliothèque, vérifiez vous-même la version de l'application et préférez les hooks d'écran, de surface, d'action et de service stables lorsqu'il en existe. La résolution de surcharge n'effectue pas de conversion de type arbitraire.", "reflectionHelpers": "Aides à la réflexion", "reflectionBridgeHelpers": "Pont de réflexion"};
messages.en = Object.assign(messages.en, {"skip": "Skip to content", "navHome": "Home", "navDocs": "Plugin docs", "heroEyebrow": "Open Android wireless toolkit", "heroTitleA": "Hack the", "heroTitleB": "World.", "heroLead": "Deadcow brings Bluetooth, infrared, NFC, HID and network tools together in a bold Material 3 Expressive interface.", "download": "Download", "androidApp": "Native Android app", "badgeText": "Pocket wireless lab", "plugins": "Plugins", "featureEyebrow": "One app. More possibilities.", "featureTitle": "A toolkit built for exploration.", "featureLead": "Scan, analyze, control and experiment with wireless technology from one carefully designed Android app.", "featureWirelessTitle": "Bluetooth & wireless", "featureWirelessBody": "Discover BLE and advertising devices, test Bluetooth audio, work with HID and explore nearby signals.", "featureIrTitle": "Infrared tools", "featureIrBody": "Use universal remotes, TV Be Gone, IR databases and signal tools with built-in or external hardware.", "featureNfcTitle": "NFC & networks", "featureNfcBody": "Read NFC tags, inspect local networks and keep useful diagnostics close at hand.", "featurePluginsTitle": "Powerful Python plugins", "featurePluginsBody": "Create screens, hook app actions and add hardware integrations with a single readable .deadcowplugin file.", "pluginEyebrow": "Made to be extended", "pluginTitle": "Turn an idea into a Deadcow tool.", "pluginLead": "The plugin engine exposes expressive UI, app hooks and Android device capabilities through a focused Python API.", "pluginPointOne": "Build complete Material 3 screens", "pluginPointTwo": "Extend existing features and actions", "pluginPointThree": "Integrate Bluetooth, Wi-Fi, USB, IR and more", "readDocs": "Read plugin docs", "downloadEyebrow": "Ready to explore?", "downloadTitle": "Get the latest Deadcow release.", "downloadLead": "Download the APK from GitHub Releases and turn your Android device into a pocket wireless toolkit.", "openReleases": "Open Releases", "footerTagline": "Hack the World.", "integrationTruthTitle": "Integration points, not arbitrary patching", "integrationTruthBody": "Screen hooks work for every route hosted by Deadcow. Action and service hooks work only where the app explicitly dispatches a named integration point. A plugin does not automatically intercept every Kotlin function.", "screenHookTitle": "Screen hooks in detail", "screenHookLead": "Routes and patterns are case-insensitive. The asterisk matches any number of characters. If several plugins match, higher priority wins where only one contribution can be used.", "modeOverlay": "Renders a full-size transparent layer over the existing screen.", "modeTop": "Places plugin UI in a Material surface at the top of the screen.", "modeBottom": "Places plugin UI above the bottom navigation area.", "modeFab": "Places compact plugin UI at the bottom end with navigation-safe padding.", "modeReplace": "The highest-priority replacement visually covers the built-in screen. Its underlying Compose screen still exists, so this is UI replacement rather than bytecode patching.", "routePatternsTitle": "Useful route patterns", "routePatternsBody": "Use the navigation event while developing to inspect the current route. Routes with arguments are reported as their navigation template, for example nfc_result/{id}.", "logicHooksTitle": "Action hooks and services", "logicHooksLead": "Action hooks form a priority-ordered pipeline. Services form a priority-ordered provider list. Both use JSON-compatible payloads.", "returnNone": "Continue without changing the action.", "returnPayload": "Replace the payload passed to lower-priority hooks and the built-in implementation.", "returnHandled": "Mark the action handled by the plugin. Use result to return a value.", "returnCancel": "Stop the hook chain and cancel the built-in operation.", "returnFalse": "Cancel immediately. True marks the action handled.", "currentPointsTitle": "Integration points available now", "currentPointsBody": "Deadcow exposes shared infrared transmission plus Bluetooth section selection, All actions, BLE modes, Advert presets and every outgoing BLE advertising packet. The complete exact list is in the hook catalog.", "fullApiTitle": "Complete runtime map", "fullApiLead": "These groups mirror the callable surface currently shipped with Deadcow. Open a group to see every public helper name.", "baseHelpers": "Plugin helpers", "uiHelpers": "Native Compose UI builders", "bridgeHelpers": "Runtime bridge", "androidHelpers": "Android, files and advanced Bluetooth", "deviceHelpers": "Wireless, network and elevated device tools", "docsEyebrow": "Developer documentation", "docsTitle": "Build something powerful for Deadcow.", "docsLead": "A plugin is one readable Python file with the .deadcowplugin extension. It can create screens, integrate hardware and extend existing Deadcow features.", "quickStart": "Quick start", "examples": "Examples", "onThisPage": "On this page", "tocOverview": "Overview", "tocMetadata": "Metadata", "tocQuick": "Quick start", "tocUi": "Expressive UI", "tocIntegration": "App integration", "tocApis": "Android & device APIs", "tocLifecycle": "Lifecycle", "tocInstall": "Install & safety", "overviewTitle": "What a plugin can do", "overviewLead": "Plugins run inside Deadcow and use the same design system and hardware access layer as the app.", "capScreens": "Create complete screens", "capScreensBody": "Compose multi-screen Material 3 Expressive tools with state and callbacks.", "capHooks": "Extend Deadcow", "capHooksBody": "Add overlays, FABs, replace screens and hook named actions.", "capHardware": "Integrate hardware", "capHardwareBody": "Work with BLE, classic Bluetooth, Wi-Fi, USB, NFC and infrared.", "capSystem": "Use Android capabilities", "capSystemBody": "Access activities, intents, storage, shell, Root and Shizuku when available.", "trustedTitle": "Power comes with responsibility", "trustedBody": "Plugins are executable Python code. Install only files you trust and review the source before granting elevated access.", "metadataTitle": "File metadata", "metadataLead": "Declare the plugin identity at the beginning of the file. Deadcow uses it for the preview and plugin library.", "copy": "Copy", "metaId": "Stable unique identifier", "metaName": "Display name", "metaVersion": "Release version", "metaAuthor": "Author or team", "metaDescription": "Short summary", "metaIcon": "Material Symbols icon name", "quickTitle": "Your first plugin", "quickLead": "Subclass BasePlugin, describe a screen and let Deadcow render it with the active app color scheme.", "uiTitle": "Expressive UI from Python", "uiLead": "UI builders create native Compose components. State updates and callbacks stay in your plugin file.", "integrationTitle": "Extend existing Deadcow features", "integrationLead": "Hooks let a plugin participate in current screens and logic without copying the app implementation.", "hookScreenBody": "Add an overlay or FAB to a route, or replace a screen with your own plugin screen.", "hookActionBody": "Observe, transform, handle or cancel a named action before the default implementation runs.", "serviceBody": "Supply a new implementation for a capability such as an external infrared transmitter.", "apisTitle": "Android and device APIs", "apisLead": "The bridge gives plugins controlled access to the platform and wireless hardware available on the device.", "apiContext": "App context", "apiActivity": "Current activity", "apiAndroid": "Intents & storage", "apiDevice": "Bluetooth, Wi-Fi, NFC, IR & USB", "apiShell": "Shell commands", "apiRoot": "Root access", "apiShizuku": "Shizuku access", "lifecycleTitle": "Plugin lifecycle", "lifecycleLead": "Keep setup, UI and cleanup predictable by using the runtime lifecycle methods.", "lifeLoad": "Plugin loaded", "lifeScreen": "Screen created", "lifeEvent": "Events & actions", "lifeUnload": "Plugin unloaded", "installTitle": "Install, update and recover", "installLead": "Deadcow handles .deadcowplugin files and shows a compact, partially expanded Material sheet before any code runs. Installation closes the sheet and confirms success with a Deadcow toast.", "stepOpen": "Open the file", "stepOpenBody": "Tap a .deadcowplugin file in your file manager and choose Deadcow.", "stepReview": "Review metadata", "stepReviewBody": "Review the icon, author, version, description and detected or declared capabilities such as DEX loading, downloads, files, hooks, Bluetooth, Wi-Fi, USB, IR, Root, Shizuku and Shell.", "stepInstall": "Install", "stepInstallBody": "Code starts only after you press Install. Reopening the file updates it.", "safeTitle": "Automatic Safe Mode", "safeBody": "If the app closes while plugin code is running, the next launch disables every plugin and offers a crash log. You can then enable plugins one by one.", "docsCtaTitle": "Ready to build?", "docsCtaBody": "Start with the examples in the Deadcow repository.", "viewExamples": "View examples", "metaLibrary": "Load before ordinary plugins and mark the file as a library", "metaDesignLibrary": "Load early and mark the file as a design library", "settingsContribTitle": "Native plugin settings", "settingsContribBody": "api.registerSettings adds Material 3 Expressive sections directly to Deadcow Settings. Switches and sliders persist in the plugin store and emit setting_changed; nav and card items open plugin screens.", "lifecycleAliasesTitle": "Accepted lifecycle names", "lifecycleAliasesBody": "Load and enable callbacks run when the session starts. Disable and unload callbacks run when it stops. Specific on_<event> handlers take precedence over on_event.", "stormHookTitle": "Example: intercept every IR Storm transmission", "stormHookLead": "IR Storm calls the shared infrared.transmit action once for every signal. The action payload does not contain the source screen, so a plugin that targets only IR Storm must remember the latest navigation event.", "stormPayloadName": "Signal or button name when available", "stormPayloadFrequency": "Carrier frequency in hertz", "stormPayloadPattern": "Alternating mark and space durations in microseconds", "stormPayloadProtocol": "Protocol label when known", "stormPayloadCode": "Original encoded value when available", "stormPayloadTimings": "Original timing representation when available", "stormScopeTitle": "What this example affects", "stormScopeBody": "It intercepts both ir_storm and other/ir_storm. Returning None on every other route preserves ordinary remotes, TV Be Gone and IR Jammer. Remove the route check to intercept every Deadcow IR transmission.", "stormModify": "Change frequency or pattern, then let Deadcow continue sending.", "stormHandle": "The plugin sent the signal; skip the built-in transmitter and report success.", "stormCancel": "Block the signal without sending it.", "stormAdapterTitle": "Built-in and external transmitters", "stormAdapterBody": "The example sends through Android's built-in ConsumerIrManager without re-entering the hook. For a USB transmitter, replace only send_to_external_ir with the device protocol implemented through api.getAndroid(), Android USB classes or a service provider.", "tocHookCatalog": "Hook catalog", "hookCatalogTitle": "Complete hook catalog", "hookCatalogLead": "Every screen route, named action, service operation and event currently emitted by Deadcow.", "hookCatalogRuleTitle": "Call and intercept are different", "hookCatalogRuleBody": "The Android and Device API lists contain functions a plugin can call. Only the entries below can be intercepted. Registering hook_action(\"*\") does not expose functions that Deadcow never dispatches.", "actionCatalogTitle": "Named action hooks", "catalogName": "Name", "catalogHandler": "Python handler", "catalogWhere": "Triggered by", "infraredActionWhere": "Every send through the shared IR backend: IR Storm, IR Jammer, TV Be Gone, universal and database remotes.", "actionCatalogNote": "Registration uses hook_action(name, priority). Wildcards are supported: bluetooth.*, bluetooth.ble.* and bluetooth.advert.preset.* can intercept whole families.", "serviceCatalogTitle": "Service providers and operations", "infraredAvailableWhere": "When Deadcow checks whether any IR transmitter is available.", "infraredTransmitWhere": "After action hooks, before the built-in ConsumerIrManager fallback.", "serviceCatalogNote": "Registration: provide_service(\"infrared.transmitter\", priority). Service identifiers are exact and do not use wildcard matching.", "eventCatalogTitle": "Events", "genericEventPayload": "Fallback for events without a specific on_<event> method", "routeCatalogTitle": "All screen routes available to hook_screen", "routeCatalogLead": "There are 108 routes in the current navigation hosts. Parameterized routes are matched by their template shown below, including braces.", "allRoutesTitle": "108 exact route names", "allRoutesHint": "Use an exact name or an asterisk pattern", "newHookTitle": "When a function is missing from this catalog", "newHookBody": "It cannot currently be intercepted through the public plugin hook API. Deadcow must add invokeActionHooks(name, payload) or invokeServices(service, operation, payload) at that Kotlin call site before plugin authors can hook it.", "manifestRulesTitle": "Manifest parsing rules", "manifestRulesBody": "The file is UTF-8 text and may be at most 48 MiB. String fields must be top-level single- or double-quoted assignments. id is lowercased, invalid characters become underscores and the result is limited to 64 characters. Missing fields fall back to the filename, version 1.0 and icon extension.", "libraryTruthTitle": "Library plugins and dependencies", "libraryTruthBody": "Library plugins start before consumers. __dependencies__ declares required plugin ids, determines startup order and prevents a consumer from starting while a dependency is missing or disabled. Java classes and objects may be exported by name and imported by dependent plugins.", "runtimeTruthTitle": "Public format and runtime", "runtimeTruthBody": "A file opened or shared as .deadcowplugin is always executed by the embedded Python runtime. The repository still contains an internal JavaScript compatibility runtime for previously stored .js plugins, but it is not the documented public .deadcowplugin authoring format.", "baseSignatureTitle": "Complete BasePlugin API", "baseSignatureBody": "These helpers delegate to the native bridge. api and ui are also available directly on self.", "moduleSectionsTitle": "Where add_module can place a card", "moduleSectionsBody": "Built-in sections are INFRARED, BLUETOOTH, OTHER and PLUGINS. Aliases such as ir, bt, ble, misc and localized names are normalized; any other text creates a custom section. order sorts cards, screen chooses the plugin screen, and icon accepts Material icon syntax.", "uiTextStyles": "headlineLarge/Medium/Small, titleLarge/Medium/Small, bodyLarge/Medium/Small and labelLarge/Medium/Small; camelCase and snake_case are accepted.", "uiColorValues": "primary/accent, muted/secondary, error/red, success/green, warning/orange, or #RGB/#ARGB/#RRGGBB/#AARRGGBB.", "uiIconValues": "A built-in alias or any bundled Material icon as style:name: filled, outlined, rounded, sharp, twotone or automirrored.", "uiImageValues": "asset path, asset:// URL, data:image/...;base64 URI or raw Base64. Scale: fit, crop, fill, fillWidth, fillHeight, inside or none.", "uiCallbackValues": "Click receives no value; text fields receive str, switches and checkboxes bool, sliders float, tabs int, and option controls the selected value.", "uiWebViewValues": "Loads either url or html, with JavaScript and DOM storage enabled. Treat remote and embedded content as trusted executable UI.", "uiSignatureTitle": "Complete UiFactory signatures", "uiSignatureBody": "Every argument below is supported by the Python runtime. Dimensions and spacing use dp.", "settingsHeaderSchema": "title", "settingsSwitchSchema": "key, title, subtitle, default: bool", "settingsSliderSchema": "key, title, subtitle, min, max, default, steps", "settingsNavSchema": "title, subtitle, icon, screen; always opens plugin/{pluginId}/{screen}", "settingsCardSchema": "title, subtitle, icon and optional screen", "settingsStorageTitle": "Storage and updates", "settingsStorageBody": "Switch and slider values use the same per-plugin JSON store as get_setting/set_setting. The host persists a value before calling on_setting_changed({key, value}); sliders emit the event when interaction finishes.", "settingKeysTitle": "Where setting keys come from", "settingKeysBody": "There is no predefined key catalog. The plugin author creates any string key and uses the same spelling when reading, writing or declaring a Settings item. Keys only collide inside the same plugin because every pluginId has a separate store. Prefer stable names such as capture_enabled or radio.power; changing a key creates a new setting.", "settingKeyContract": "Any non-empty string chosen by the plugin. There are currently no reserved host keys.", "settingValueContract": "Any json.dumps-compatible value: None, bool, number, str, list or dict.", "settingDefaultContract": "get_setting returns the supplied default when the key has never been saved.", "settingLifetimeContract": "Values survive restarts and enable/disable. Deleting the plugin removes its entire settings store.", "layerBase": "Convenience helpers for modules, navigation, state, screen/action/service hooks and shell access.", "layerUi": "Builds a JSON-compatible UI tree rendered as native Compose Material 3 components.", "layerBridge": "Registration, Context/Activity access, persistent JSON settings, execution and batched BLE scanning.", "layerAndroid": "Direct Android integration: storage, assets, media, crypto, IR, classic Bluetooth, RFCOMM, GATT, BLE server/advertiser, Wi-Fi and NSD.", "layerDevice": "Higher-level wireless, NFC, network, Root and Shizuku operations with JSON-oriented results.", "layerJava": "Chaquopy can import Android and Java classes directly when a bridge helper is not enough.", "apiContractsTitle": "Data and execution contracts", "apiContractsBody": "Most hardware helpers do not open permission prompts. Check hasPermission/capability methods and request Android permissions through Activity APIs when needed. Long-running scans, GATT, RFCOMM, sensors, audio, advertising, BLE servers, NSD and Wi-Fi P2P must be stopped during on_plugin_disable/on_plugin_unload.", "bridgeSignatureTitle": "Direct bridge signatures", "bridgeSignatureBody": "Use BasePlugin wrappers where they exist. Direct bridge methods preserve Java return types; settings and command methods exchange JSON text.", "deviceCompleteTitle": "Device control and system tools", "deviceCompleteBody": "Device status, radio controls and advanced Root operations", "genericActionBody": "Generic fallback for every registered action without a matching hook_<normalized_action> method. Dots and other non-alphanumeric characters normalize to underscores.", "serviceAvailableContract": "Makes an external transmitter count as available; {\"ok\": true} or raw True are also accepted.", "serviceTransmitContract": "Stops provider fallback and reports success. handled false lets the next provider or built-in ConsumerIrManager run.", "serviceGenericContract": "Generic fallback when service_<service>_<operation> is not defined.", "screenResolverContract": "Primary renderer. main also accepts create_screen or screen_main. Missing screens render a native error placeholder.", "callbackContract": "Python callables passed into UI builders receive only the value type produced by that component. Declaring fewer positional arguments is supported.", "eventResolverContract": "Specific event handler wins; otherwise on_event(name, payload) is called.", "actionResolverContract": "Specific normalized action handler wins; otherwise on_action(action, payload) is called.", "serviceResolverContract": "Specific normalized service handler wins; otherwise on_service(id, operation, payload) is called.", "refreshContract": "Invalidates registered plugin UI so screen functions run again with the latest plugin state.", "installPreviewContract": "Reads metadata and size without executing Python; shows whether the same id is already installed.", "installUpdateContract": "Saves the source privately and starts it immediately unless Safe Mode is active. Installing the same id replaces the previous session and keeps its pinned state.", "installToggleContract": "Starts or stops the runtime and removes all registered modules, settings, screens, services and actions when disabled.", "installShareContract": "Pin changes ordering. Share exports the original source as application/x-deadcow-plugin with the .deadcowplugin extension.", "installDeleteContract": "Stops the runtime and permanently removes source, metadata, registrations and the plugin private settings store.", "installFailureContract": "A plugin that cannot start is saved disabled during installation; a corrupt stored source can be quarantined as .broken during restoration.", "safeDetailsTitle": "Safe Mode behavior", "safeDetailsBody": "The recovery sheet explains that a plugin error closed the app and offers Copy log or Disable Safe Mode. Dismissing it leaves Safe Mode enabled and a persistent item remains on the Plugins screen. While active, every plugin is disabled and cannot be enabled until Safe Mode is turned off.", "coreReplaceTitle": "Replace complete core screens", "coreReplaceBody": "Use replace with other, bluetooth or settings to cover the complete core screen. Bluetooth also exposes three live sub-screen targets, so a plugin can replace All, BLE or Advert independently.", "bleHookTitle": "Example: replace BLE advertising logic", "bleHookLead": "bluetooth.advertising.transmit runs for custom Advert presets and packets generated by every built-in BLE spam mode. Change data to rewrite the packet, return cancel to block it, or handled after transmitting with your own backend.", "bleModeApiTitle": "Add a first-class BLE Spam mode", "bleModeApiLead": "register_ble_mode adds the plugin beside the built-in BLE modes using the same card, active state, shared delay and Stop All behavior. Deadcow sends ble_mode_start, ble_mode_stop and ble_mode_delay_changed only to the owning plugin. The plugin owns its advertising loop and must stop it on both stop and unload.", "assetApiTitle": "Download and apply plugin assets", "assetApiLead": "download_assets requests all files as one batch. Each destination is confined to this plugin’s private directory; maxBytes limits each response and sha256 can verify it. Unless the user disabled confirmation in Plugin settings → Security, Deadcow shows the plugin name, file count and declared total size before network transfer. apply_asset imports a saved file into a stock Bad USB editor, user IR remotes or QR Audio Spoofer custom HTML.", "assetPathContract": "Returns the absolute path of a location inside the plugin’s private folder for Java and DEX APIs.", "assetDownloadContract": "Items accept url, path, sizeBytes, maxBytes, sha256 and headers. The callback receives {ok, files} as JSON text.", "assetApplyContract": "Supported types: bad_hid, ir_remote and qr_audio_html. Returns a parsed result dictionary.", "bleAssetHelpers": "BLE modes and plugin assets", "bleAssetBridgeHelpers": "BLE and asset bridge", "metaPermissions": "Capabilities shown before installation; Deadcow also detects direct API usage in the source", "btSectionWhere": "Before switching between All, BLE and Advert. section or index may be changed.", "btDeviceWhere": "Before selecting a discovered classic Bluetooth device.", "btIntervalWhere": "When the All interval slider changes. intervalMs may be changed.", "btScanWhere": "Before classic and BLE discovery starts on All.", "btAllStartWhere": "Before All starts repeated classic pairing requests.", "btAllStopWhere": "Before All stops its active operation.", "bleDelayWhere": "Before changing the BLE mode delay. delayMs may be changed.", "bleModeWhere": "Before toggling an individual BLE mode.", "bleKitchenWhere": "Before toggling Kitchen Sink.", "bleStopWhere": "Before stopping all BLE modes.", "bleSectionToggleWhere": "Before toggling every mode in an iOS, Samsung, Android, Windows, Xiaomi or Phantom group.", "bleSectionOpenWhere": "Before opening a BLE group screen. section may be redirected.", "advertAddWhere": "Before saving a new Advert preset; all fields may be changed.", "advertUpdateWhere": "Before updating an Advert preset; all fields may be changed.", "advertDeleteWhere": "Before deleting an Advert preset.", "advertStartWhere": "Before starting a preset; fields may be changed or the start may be fully handled.", "advertStopWhere": "Before stopping an Advert preset.", "advertTransmitWhere": "Before every outgoing advertising packet from Advert or built-in BLE modes.", "advertisingStopWhere": "Before an Advert cycle or built-in BLE advertiser stops; an external backend can stop its own transmission and return handled.", "advertPayloadTitle": "bluetooth.advertising.transmit payload", "advertPayloadBody": "metadata.source is ble_spam or advert; Advert also includes metadata.preset. data and scanResponse contain includeDeviceName, includeTxPowerLevel, manufacturerData [{id,data}], serviceUuids and serviceData [{uuid,data}]. Binary values are uppercase hex. Returning a modified payload rebuilds the native AdvertiseData.", "virtualRoutesTitle": "Bluetooth sub-screen targets", "virtualRoutesBody": "These are live hook targets inside the bluetooth route rather than navigation destinations. They support every hook_screen mode.", "tocSdkReference": "SDK reference", "sdkReferenceTitle": "Callable SDK reference", "sdkReferenceLead": "Search the complete public API. Every entry includes its exact signature, parameters, return contract, requirements and a Python call example.", "sdkReadingTitle": "How to read the contracts", "sdkReadingBody": "A nullable type can become None. Boolean actions report whether Android accepted the request, not whether a remote device completed it. Methods with callbacks finish asynchronously. JSON results remain strings until json.loads is called.", "tocDexLibraries": "DEX & libraries", "metaDependencies": "Required plugin ids loaded before this plugin", "surfaceHooksTitle": "App chrome surfaces", "surfaceHooksBody": "hook_surface targets UI outside an ordinary screen route. bottom_bar can be overlaid or fully replaced. The replacement follows plugin priority and disappears automatically when the plugin is disabled.", "surfaceCatalogTitle": "Hookable host surfaces", "surfaceCatalogBody": "Use hook_surface rather than hook_screen for UI owned by the app shell.", "dexLibrariesTitle": "DEX loading and library plugins", "dexLibrariesLead": "Keep a plugin as one readable Python file while embedding compiled Java or Kotlin code and sharing native capabilities with other plugins.", "dexTrustTitle": "DEX is native trusted code", "dexTrustBody": "A loaded DEX runs inside the Deadcow process with the app permissions. Always publish the SHA-256, verify it before loading and never execute an untrusted downloaded payload.", "dexEmbeddedTitle": "Embed and load a raw DEX", "dexEmbeddedLead": "Store the raw DEX as Base64 in the .deadcowplugin file. Deadcow removes whitespace, decodes it, verifies SHA-256 and creates the class loader. Raw DEX uses InMemoryDexClassLoader on Android 8+; older Android and ZIP-based JAR/APK payloads use a private read-only code-cache file and DexClassLoader.", "dexLoadBase64Contract": "Loads raw DEX, JAR or APK bytes stored as Base64 and returns the module ClassLoader.", "dexLoadFileContract": "Copies and loads a DEX/JAR/APK file. Use plugin-private storage and verify its digest.", "dexClassContract": "Loads a Class from a module owned by the current plugin.", "dexInstanceContract": "Calls an accessible no-argument constructor and returns the Java object.", "dexLoaderContract": "Returns an already loaded module ClassLoader or None.", "dexDependencyLoaderContract": "Returns an app parent loader which can also resolve modules exported by declared dependencies.", "libraryExportsTitle": "Export classes and live objects", "libraryExportsLead": "Exports are process-local named references. A library owns every class and object it exports; disabling, updating or deleting that library removes its modules and exports from the registry.", "exportDexClassBody": "Resolve and publish a class from the current DEX module.", "exportAppClassBody": "Publish a Deadcow or dependency class by its fully qualified name.", "exportJavaClassBody": "Publish a Class object already obtained through Java reflection.", "exportJavaObjectBody": "Publish a live Java object, adapter, controller or facade.", "importJavaClassBody": "Get a named Class export from any enabled dependency.", "importJavaObjectBody": "Get a named live object export from any enabled dependency.", "javaExportsBody": "Inspect all loaded modules and exported class/object names for diagnostics.", "sourceBridgeTitle": "Expose Deadcow internals from open source", "sourceBridgeLead": "Use the repository to find a fully qualified JVM class name, then export that Class or wrap it in a stable DEX facade. Consumers should depend on the library facade instead of duplicating fragile reflection code.", "sourceBridgeBoundaryTitle": "Class access versus host hooks", "sourceBridgeBoundaryBody": "Class export enables reflection, construction and method calls; it does not rewrite an already compiled Compose function. Use hook_screen for screens, hook_surface(\"bottom_bar\") for the navigation panel, action hooks for logic and service providers for replaceable hardware backends. A DEX library can hide reflection behind a stable facade shared by other plugins.", "dexLimitsTitle": "Limits and lifecycle", "dexLimitsBody": "A .deadcowplugin may be 48 MiB; each decoded DEX/JAR/APK payload may be 32 MiB. Disabling, deleting or updating a library automatically disables enabled dependent plugins first; re-enable consumers when the library is ready. Android cannot unload a Class once code has referenced it. Deadcow drops loaders and exports when the owner stops, but a process restart is the only guaranteed complete unload after an update. Keep export names globally unique and close threads, receivers, sockets and hardware handles in on_plugin_unload.", "docsSearch": "Search documentation", "tocStartGroup": "Getting started", "tocUiGroup": "Interface", "tocIntegrationGroup": "Integration", "tocNativeGroup": "Native code", "tocReferenceGroup": "Reference", "tocPluginSettings": "Plugin settings", "tocScreenHooks": "Screen hooks", "tocSurfaceHooks": "App surfaces", "tocLogicHooks": "Actions & services", "tocLibraryExports": "Library exports", "tocReflection": "Java reflection", "reflectionTitle": "Java reflection helpers", "reflectionLead": "These helpers search the app plus DEX modules of declared dependencies. They can inspect private members, read or write fields, call a matching method and construct an object. They do not install a method hook and do not intercept future calls.", "reflectionFind": "Returns a Class or None using the app and dependency ClassLoaders.", "reflectionInspect": "Returns className plus inherited fields, methods, constructors, parameter types and static flags.", "reflectionGet": "Reads a public or private instance field. Pass a Class for a static field.", "reflectionSet": "Writes a public or private instance field. Pass a Class for a static field.", "reflectionInvoke": "Calls the first compatible overload by name, argument count and runtime types. Pass a Class for a static method.", "reflectionNew": "Calls the first compatible declared constructor, including a private constructor.", "reflectionLimitsTitle": "Reflection compatibility", "reflectionLimitsBody": "Private names and signatures may change between Deadcow builds. Catch exceptions, declare the library dependency, verify the app version yourself and prefer stable screen, surface, action and service hooks whenever one exists. Overload resolution does not perform arbitrary type conversion.", "reflectionHelpers": "Reflection helpers", "reflectionBridgeHelpers": "Reflection bridge"});

const pageText = {
  home: {
    fr: ['Deadcow — Arsenal sans-fil & pentest matériel', 'Deadcow rassemble les technologies Bluetooth, infrarouge, NFC, HID et réseau dans une interface Material 3 Expressive pour la communauté CDC et le collectif Deadcow.'],
    en: ['Deadcow — Wireless toolkit for Android', 'Deadcow is an expressive Android toolkit for Bluetooth, infrared, NFC, HID, networks and Python plugins.'],
    ru: ['Deadcow — беспроводные инструменты для Android', 'Deadcow — выразительный Android-набор для Bluetooth, ИК, NFC, HID, сетей и Python-плагинов.']
  },
  docs: {
    fr: ['Documentation des Plugins Deadcow', 'Documentation officielle pour créer des extensions Python pour Deadcow.'],
    en: ['Deadcow Plugin Documentation', 'Documentation for creating Python plugin extensions for Deadcow.'],
    ru: ['Документация плагинов Deadcow', 'Документация по созданию Python-расширений для Deadcow.']
  }
};

const storedLanguage = localStorage.getItem('deadcow-language');
const browserLanguage = (navigator.languages?.[0] || navigator.language || 'fr').toLowerCase();
let language = storedLanguage || (browserLanguage.startsWith('ru') ? 'ru' : (browserLanguage.startsWith('en') ? 'en' : 'fr'));
if (!['fr', 'en', 'ru'].includes(language)) language = 'fr';

function setLanguage(nextLanguage) {
  language = ['fr', 'en', 'ru'].includes(nextLanguage) ? nextLanguage : 'fr';
  document.documentElement.lang = language;
  
  const dict = messages[language] || messages.fr || messages.en;
  
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const value = dict[element.dataset.i18n];
    if (value) element.textContent = value;
  });
  
  document.querySelectorAll('[data-i18n-placeholder]').forEach(element => {
    const value = dict[element.dataset.i18nPlaceholder];
    if (value) element.placeholder = value;
  });
  
  document.querySelectorAll('[data-language-label]').forEach(element => {
    element.textContent = language === 'fr' ? 'FR' : (language === 'ru' ? 'RU' : 'EN');
  });
  
  const page = (document.body && document.body.dataset && document.body.dataset.page) || 'home';
  if (pageText[page] && pageText[page][language]) {
    const [title, description] = pageText[page][language];
    document.title = title;
    const meta = document.querySelector('meta[name="description"]');
    if (meta) meta.content = description;
  }
  
  try {
    localStorage.setItem('deadcow-language', language);
  } catch (e) {}
}

document.querySelectorAll('[data-language-toggle]').forEach(button => {
  button.addEventListener('click', () => {
    const order = ['fr', 'en', 'ru'];
    const nextIdx = (order.indexOf(language) + 1) % order.length;
    setLanguage(order[nextIdx]);
  });
});

document.querySelectorAll('[data-current-year]').forEach(element => {
  element.textContent = new Date().getFullYear()
})

document.querySelectorAll('.copy-button, .copy-code').forEach(button => {
  button.addEventListener('click', async () => {
    const code = button.closest('.code-block, .code-card')?.querySelector('code')?.innerText || ''
    await navigator.clipboard.writeText(code)
    const label = button.querySelector('[data-i18n]')
    if (label) label.textContent = language === 'ru' ? 'Скопировано' : 'Copied'
    setTimeout(() => {
      if (label) label.textContent = messages[language].copy
    }, 1400)
  })
})

const revealObserver = new IntersectionObserver(entries => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible')
      revealObserver.unobserve(entry.target)
    }
  })
}, { threshold: .01 })

document.querySelectorAll('.reveal').forEach(element => revealObserver.observe(element))

const tocLinks = [...document.querySelectorAll('.docs-toc a')]
const docNavSearch = document.querySelector('[data-doc-nav-search]')
if (docNavSearch) {
  docNavSearch.addEventListener('input', () => {
    const query = docNavSearch.value.trim().toLowerCase()
    tocLinks.forEach(link => { link.hidden = query && !link.textContent.toLowerCase().includes(query) })
    document.querySelectorAll('.docs-toc .toc-title').forEach(title => {
      let sibling = title.nextElementSibling
      let visible = false
      while (sibling && !sibling.classList.contains('toc-title')) {
        if (sibling.matches('a') && !sibling.hidden) visible = true
        sibling = sibling.nextElementSibling
      }
      title.hidden = Boolean(query) && !visible
    })
  })
}
const docSections = [...document.querySelectorAll('.doc-section[id]')]
if (tocLinks.length && docSections.length) {
  const tocObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        tocLinks.forEach(link => link.classList.toggle('active', link.getAttribute('href') === `#${entry.target.id}`))
      }
    })
  }, { rootMargin: '-25% 0px -65% 0px' })
  docSections.forEach(section => tocObserver.observe(section))
}

setLanguage(language)
